import {d,label,read,title,capture,log,foreground,tap,out,uid,bid} from './sb40-photos-ios-helper-20261108.mjs';import assert from 'node:assert/strict';import fs from 'node:fs';import {execFileSync} from 'node:child_process';
const target=()=>read().data.memories.find(m=>m.title===title);const photos=()=>{const s=read();return s.data.memories.find(m=>m.title===title).mediaIds.map(id=>s.data.media.media.find(p=>p.id===id));};
async function waitFor(check){for(let i=0;i<60;i++){if(check())return;await new Promise(r=>setTimeout(r,200));}throw Error('Photo write did not settle');}
async function photosTab(){await d.screen.tap(151,805);}
async function control(t){for(let i=0;i<14;i++){let found;const walk=nodes=>{for(const n of nodes){if(n.label===t&&n.type==='Button')found=n;walk(n.children??[]);}};walk(await d.screen.viewTree());const box=found?.bounds,y=box?box.y+box.height/2:null,top=580,bottom=830;if(box&&y>=top&&y<=bottom){await label(t).tap();await new Promise(r=>setTimeout(r,250));return;}const down=y===null?['Next photo','Previous photo','Manage photos'].includes(t):y<top;await d.screen.gesture({pointers:[[{x:200,y:down?620:805,time:0},{x:200,y:down?805:620,time:500}]]});}throw Error('Unreachable viewer control '+t);}

async function addPhoto(x,count){await control('Add Photo');await label('Choose from Library').tap();await new Promise(r=>setTimeout(r,4000));await d.screen.tap(x,207);await waitFor(()=>photos().length===count);}
try{assert.ok(photos().length>=1&&photos().length<=2);await foreground();await label('CasitaDex logo, go to Home').tap();await photosTab();await tap(label('View photo 1 of '+title+' full screen'));await control('Manage photos');if(photos().length===1)await addPhoto(201,2);await addPhoto(335,3);const before=photos();assert.equal(new Set(before.map(p=>p.sha256)).size,3);log('shared-viewer-adds-three-distinct-native-photos');
 await control('Next photo');await control('Use as cover photo');await waitFor(()=>target().mediaIds[0]===before[1].id);log('cover-selection-persists-without-byte-change');await control('Move photo later');await waitFor(()=>target().mediaIds[1]===before[1].id);await control('Move photo earlier');await waitFor(()=>target().mediaIds[0]===before[1].id);log('photo-order-moves-earlier-and-later');await capture('ios-cover-order');
 await control('Replace this photo');await label('Cancel').tap();assert.deepEqual(target().mediaIds, [before[1].id,before[0].id,before[2].id]);log('replace-cancel-keeps-order-and-photos');await control('Replace this photo');await label('Choose from Library').tap();await new Promise(r=>setTimeout(r,4000));await d.screen.tap(67,207);await waitFor(()=>!target().mediaIds.includes(before[1].id));assert.equal(photos().length,3);log('replace-photo-retains-count-and-position');
 const ids=[...target().mediaIds];await control('Remove this photo');await label('Cancel').tap();assert.deepEqual(target().mediaIds,ids);log('remove-cancel-keeps-photo');await control('Remove this photo');await label('Remove photo').tap();await waitFor(()=>photos().length===2);assert.deepEqual(target().mediaIds,[before[0].id,before[2].id]);log('confirmed-photo-removal-keeps-other-photos');await capture('ios-photo-actions');await label('Close photo').tap();await label('Compact photo view').tap();
 execFileSync('xcrun',['simctl','terminate',uid,bid]);execFileSync('xcrun',['simctl','launch',uid,bid]);await foreground();await photosTab();await capture('ios-photos-after-relaunch');assert.deepEqual(target().mediaIds,[before[0].id,before[2].id]);const baseline=JSON.parse(fs.readFileSync(out+'/ios-before.json','utf8')),after=read();for(const m of baseline.data.memories)assert.deepEqual(after.data.memories.find(x=>x.id===m.id),m);for(const p of baseline.data.media.media)assert.deepEqual(after.data.media.media.find(x=>x.id===p.id),p);assert.equal(after.draft,null);log('photo-order-survives-relaunch-and-original168-records-unchanged');fs.writeFileSync(out+'/ios-after.json',JSON.stringify(after,null,2));
}catch(e){await capture('ios-manage-failure');throw e;}finally{await d.close();}
